css:
@page { size: 20mm 40mm; margin: 0; }
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { width: 20mm; background: #fff; }
.pg { width: 20mm; height: 40mm; overflow: hidden; position: relative;
      page-break-after: always; break-after: page; page-break-inside: avoid; break-inside: avoid; }
.pg:last-child { page-break-after: auto; break-after: auto; }
body { font-family: Arial, 'Segoe UI', 'Tajawal', sans-serif; color: #000;
       -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.lbl {
  width: 40mm; height: 20mm; padding: 0.8mm 1.5mm; overflow: hidden;
  display: flex; flex-direction: column; align-items: center; justify-content: space-between;
  gap: 0.3mm; position: absolute; top: 0; left: 0; transform-origin: top left; transform: translateX(20mm) rotate(90deg);

}
.lbl-s { font-size: 4.5pt; text-transform: uppercase; letter-spacing: 0.3px; line-height: 1; }
.lbl-n { width: 100%; font-size: 6pt; font-weight: 700; text-align: center; line-height: 1.1;
         display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden;
         word-break: break-word; }
.lbl-b { width: 100%; flex: 1 1 auto; min-height: 0; display: flex; align-items: center; justify-content: center; }
.lbl-b svg { width: 100%; height: 100%; display: block; }
.lbl-p { font-size: 7.5pt; font-weight: 800; font-family: Arial, sans-serif; line-height: 1; white-space: nowrap; }
@media screen {
  html, body { width: auto; } body { background: #e5e7eb; padding: 10px; }
  .pg { background: #fff; margin: 0 auto 8px; box-shadow: 0 1px 3px rgba(0,0,0,.25); }
}

